-- Imported values leave intake; canon holds them now.
delete from xpms.intake i
 using xpms.playbook_sourced_value s
 where i.source_file = s.source_file and i.source_sheet = s.source_sheet
   and i.source_row = s.source_row and i.source_column = s.source_column;

