-- The 18 Playbook field targets that waited on the decision (finding A47-001).
insert into xpms.playbook_column (sheet_name, ordinal, letter, header, column_key, disposition, target, data_type, note) values
  ('Asset Inventory', 16, 'P', 'STATUS', 'status', 'field', 'app.asset_units.asset_state', 'text', 'Asset state (owner decision 25): Active maps to the closest existing state, Available (xpms.label_mapping). No state is added.'),
  ('Budget Expenses', 28, 'AB', 'VENDOR', 'vendor', 'field', 'app.purchase_orders.vendor_id', 'text', 'Vendor of the purchase order whose line draws on this budget line (po_lines.budget_line_id). Owner decision 25: Landlord is not a canon counterparty type, so the Landlord resolves to a counterparty of the existing type Facilities Services (xpms.label_mapping); a cell holding the Landlord''s proposal note resolves the same way.'),
  ('Budget Expenses', 29, 'AC', 'STATUS', 'status', 'field', 'xpms.production_template_values.value_text', 'text', 'Template only: budget lines have no lifecycle column, and owner decision 25 adds none. Open maps to the canon state Active and Estimated to Quoted (xpms.label_mapping); a line''s commitment is derived from the purchase order lines that draw on it.'),
  ('Change Orders', 8, 'H', 'CHANGE ORDER TYPE', 'change_order_type', 'field', 'app.change_orders.order_type_enum_id', 'text', 'Order Type enumeration row (Standard Library) matched by label. Owner decision 25: Scope Addition maps to Scope Expansion and Material Upgrade to Equipment Substitution (xpms.label_mapping).'),
  ('Crew Shifts', 19, 'S', 'STATUS', 'status', 'field', 'app.shifts.shift_state', 'text', 'Shift state (owner decision 25): Confirmed maps to the closest existing state, Accepted (xpms.label_mapping). No state is added.'),
  ('Locations', 3, 'C', 'DEPARTMENT', 'department', 'field', 'app.spaces.urid', 'text', 'Department segment of the space''s URID. Owner decision 25: each Locations department label maps to the closest canon department (xpms.label_mapping); where the category''s URID sits in another department, the URID wins (the Bible wins on hierarchy).'),
  ('Locations', 4, 'D', 'CATEGORY', 'category', 'field', 'app.spaces.urid', 'text', 'Category of the space''s URID. Owner decision 25: each Locations category label maps to the closest canon category (xpms.label_mapping).'),
  ('Locations', 5, 'E', 'SUB CATEGORY', 'sub_category', 'field', 'xpms.production_template_values.value_text', 'text', 'Template only: the URID has no fourth segment (Section 3.3), so a sub category below the category has no column; the label stays in the template.'),
  ('Marshalling Yard Log', 21, 'U', 'STATUS', 'status', 'field', 'app.gate_queue.arrived_at', 'text', 'Derived, not stored. Owner decision 25: log entries have no lifecycle column and none is added; Staged maps to the closest canon state, Ready, which holds while the vehicle has checked in (gate_queue.arrived_at) and is not released (xpms.label_mapping).'),
  ('Production Schedule', 10, 'J', 'ACTIVITY TYPE', 'activity_type', 'field', 'app.records.record_kind', 'text', 'Record kind (owner decision 25): Summary Activity maps to Timeline and Milestone Gate to Milestone, the closest of the 26 record kinds (xpms.label_mapping).'),
  ('Production Tasks', 17, 'Q', 'PRIORITY', 'priority', 'field', 'xpms.production_template_values.value_text', 'text', 'Template only: records have no priority, and owner decision 25 adds no structure the Bible lacks (the Bible wins on structure), so the label stays in the template. Incident Priority is a different list.'),
  ('Projects', 16, 'P', 'OPERATIONAL STATE', 'operational_state', 'field', 'app.projects.production_state', 'text', 'Production lifecycle state (owner decision 25): Active and Complete are production states; Scheduled maps to the closest existing state, Active (xpms.label_mapping). No state is added.'),
  ('Shipping Manifest', 27, 'AA', 'FREIGHT TYPE', 'freight_type', 'field', 'app.shipments.freight_type_enum_id', 'text', 'Freight Type enumeration row (Standard Library) matched by label. Owner decision 25: Ground Freight maps to the closest existing label, Full Truckload (xpms.label_mapping).'),
  ('Shipping Manifest', 30, 'AD', 'STATUS', 'status', 'field', 'app.shipments.ships_at', 'text', 'Derived, not stored. Owner decision 25: shipments have no lifecycle column and none is added; Scheduled is the canon state Scheduled, which holds while ships_at is set and the freight has not arrived (xpms.label_mapping).'),
  ('Staffing Requisition', 2, 'B', 'EVENT PHASE', 'event_phase', 'field', 'app.budget_lines.phase_code', 'text', 'Phase of the budget line the requisition draws on (requisitions.budget_line_id). Owner decision 25: each event phase maps to the closest of the nine canon phases (xpms.label_mapping).'),
  ('Work Orders', 6, 'F', 'WORK ORDER TYPE', 'work_order_type', 'field', 'app.records.record_subtype', 'text', 'Subtype of the work order''s record (work_orders.record_id), a Build record. Owner decision 25: AVL Installation, Network Deployment and Rigging & Focus map to Systems, Facility Setup to Structural and Security Commissioning to Commissioning (xpms.label_mapping).'),
  ('Work Orders', 7, 'G', 'PRIORITY', 'priority', 'field', 'xpms.production_template_values.value_text', 'text', 'Template only: records have no priority, and owner decision 25 adds no structure the Bible lacks (the Bible wins on structure), so the label stays in the template. Incident Priority is a different list.'),
  ('Work Orders', 27, 'AA', 'STATUS', 'status', 'field', 'app.work_orders.work_order_state', 'text', 'Work order state (owner decision 25): Completed maps to Complete, In Progress is a state, and Scheduled maps to the closest existing state, Awarded (xpms.label_mapping). No state is added.')
on conflict (sheet_name, ordinal) do update set
  letter = excluded.letter,
  header = excluded.header,
  column_key = excluded.column_key,
  disposition = excluded.disposition,
  target = excluded.target,
  data_type = excluded.data_type,
  note = excluded.note;

